"""Write the count theorems for a network already generated by gen_lean.py: how many pairs it gets right.

Usage: python3 gen_count.py NETWORK.npz NAME CHUNKS
  NAME    the namespace gen_lean.py wrote (its Weights.lean and Table.lean must exist)
  CHUNKS  number of files the row theorems are split into

For each row a (first input), one kernel evaluation decides the fast evaluator's checks on the row
and the exact number of b < p with the right answer (`row_a`). Count.lean sums the rows into
`right_on_N`, the number of pairs the network answers correctly, by the plain definition in
Network.lean (`count` in Count.lean), via `rowCount_eq_fastRowCount`.
"""
import sys
from pathlib import Path
import numpy as np

src, name, chunks = sys.argv[1], sys.argv[2], int(sys.argv[3])
net = np.load(src)
p, H = int(net["p"]), int(net["H"])
E1, E2, W2 = net["E1q"], net["E2q"], net["W2q"]
a, b = np.divmod(np.arange(p * p), p)
ans = ((E1[a] + E2[b]) ** 2 @ W2.T).argmax(1)
right = ans == (a + b) % p
rows = [int(right[a == r].sum()) for r in range(p)]
total = sum(rows)
root = Path("lean/LeanCheckedNetwork") / name
assert (root / "Table.lean").exists(), f"{root}/Table.lean missing: run gen_lean.py first"

for i, rs in enumerate(np.array_split(np.arange(p), chunks)):
    body = "\n".join(f"""theorem row_{r} : rowOk E1 E2 {H} {p} {r} = true ∧ fastRowCount E1 E2 W2 {H} {p} {r} = {rows[r]} := by
  decide +kernel
""" for r in map(int, rs))
    (root / f"Count{i:02d}.lean").write_text(f"""import LeanCheckedNetwork.Count
import LeanCheckedNetwork.{name}.Table

/-! Rows {int(rs[0])} to {int(rs[-1])}: the fast evaluator's checks pass and the number of right answers, by the kernel. -/

set_option Elab.async false

namespace LeanCheckedNetwork.{name}

open LeanCheckedNetwork

{body}
end LeanCheckedNetwork.{name}
""")

imports = "\n".join(f"import LeanCheckedNetwork.{name}.Count{i:02d}" for i in range(chunks))
uses = "\n".join(f"    row_{r}.2, rowCount_eq_fastRowCount E1 E2 W2 {H} {p} {r} table_ok row_{r}.1," for r in range(p))
uses = uses.rstrip(",")
(root / "Count.lean").write_text(f"""{imports}

/-!
# How many pairs the network gets right

`right_on_{total}`: the network answers `(a + b) % {p}` on exactly {total} of the {p * p} pairs
({p * p - total} wrong). One kernel evaluation per row, then the sum. Generated by `gen_count.py`
from `{src}`.
-/

namespace LeanCheckedNetwork.{name}

open LeanCheckedNetwork

/-- The network answers `(a + b) % {p}` on exactly {total} of the {p * p} pairs. -/
theorem right_on_{total} : count E1 E2 W2 {p} = {total} := by
  unfold count
  simp only [List.range_succ, List.map_append, List.map_cons, List.map_nil, List.sum_append,
    List.sum_cons, List.sum_nil, List.range_zero,
{uses}]
  rfl

end LeanCheckedNetwork.{name}
""")
print(f"wrote {root}: {chunks} count files, right on {total} of {p * p}, wrong rows {sum(1 for r in rows if r < p)}")
